Method.Implementation:
 $$$TRACE("...In insertUpdatePerson method")
 Set ..Adapter.WebServiceClientClass = "EnterprisePersonService.SOAP11Endpoint"

 try{
     Set tSC = ..Adapter.InvokeMethod("insertUpdatePerson",.patientIdElement,pRequest.Patient,pRequest.sourceSystemIdentification,pRequest.codeSystem,.warnings)
     $$$TRACE("...In insertUpdatePerson method .. Status.."_tSC)
     if ('tSC){
     	set errText = $System.Status.GetErrorText(tSC)
     	$$$TRACE("...In insertUpdatePerson method .. ERROR.."_errText)     	
     	If errText["ERROR #6248:"{	
     	    throw $$$ERROR(6248," Soap Fault Exception in InsertAddUpdate Response: "_errText)     	    
     	}
     }else{
	     $$$TRACE("...In insertUpdatePerson method .. NO ERROR")
	     }
 }
 CATCH exceptionvar
    {
	    set errTxt = $System.Status.GetErrorText(%objlasterror)
	    $$$TRACE("...In insertUpdatePerson method .. Catch Block.."_errTxt)	        		
		$$$TRACE($ZERROR)
		If errTxt["ERROR #6248:"{			       
                throw exceptionvar                
		}   

    }      

 Set tSC = pRequest.NewResponse(.pResponse)  Quit:$$$ISERR(tSC) tSC 
 $$$TRACE("...In insertUpdatePerson method .. Warnings "_$get(warnings))

 Set pResponse.patientIdElement=$get(patientIdElement),pResponse.warnings = $get(warnings)

 if ($length(pResponse.patientIdElement) > 0){
	 $$$TRACE("...Patient MRN: "_pResponse.patientIdElement)
	 	 } else{
		 	 set tSC = $$$ERROR(6246,"Exception in InsertAddUpdate Initiate Webservice Operation")
		 	 Quit tSC

		 	 }

 $$$TRACE("...In insertUpdatePerson method .. DONE!!!!!!")
 Quit $$$OK
